import { Box } from '@chakra-ui/react'
import { Routes, Route } from 'react-router-dom'
import { Navigate } from 'react-router-dom'
import { useEffect } from 'react'
import { useAuthStore } from '../store/auth'

import Layout from '../adminPages/Layout'
import Reservations from '../adminPages/Reservations'
import InUsePage from '../adminPages/In-UsePage'
import Listings from '../adminPages/Listings'
import CreatePage from '../adminPages/CreatePage'
import ReturnedResources from '../adminPages/ReturnedResources'
import AdminAccounts from '../adminPages/AdminAccounts'
import ResidentAccounts from '../adminPages/ResidentAccounts'
import UnverifiedResidents from '../adminPages/UnverifiedResident'
import RegistrationKey from '../adminPages/RegistrationKey'
import AdminSignupPage from '../adminPages/AdminSignupPage'
import LoadingSpinner from '../components/LoadingSpinner'
import AdminLogs from '../adminPages/AdminLogs'
import NotFound from '../components/NotFound'
import PropTypes from 'prop-types';

//protect routes that require authentication
const ProtectedRoute = ({children}) => {
    const {isAuthenticated, user} = useAuthStore()
    
    if (!isAuthenticated) {
      return <Navigate to='/auth/admin-login' replace />
    }
    if (!user?.isVerified) {
      return <Navigate to='/auth/verify-signup-otp' replace />
    }
    return children;
  }

function AdminApp() {
    const { checkAuth, isCheckingAuth } = useAuthStore()

    useEffect(() => {
      checkAuth()
      if (checkAuth) {}
    }, [checkAuth])

    if(isCheckingAuth) {
        return <LoadingSpinner />
    }
  return (
    <Box>
      <ProtectedRoute>
      <Layout>
        <Routes>
        <Route path='reservations' element={<Reservations />}/>
        <Route path='in-use-resources' element={<InUsePage />}/>
        <Route path='listings' element={<Listings />}/>
        <Route path='create-listing' element={<CreatePage />}/>
        <Route path='returned-resources' element={<ReturnedResources />}/>
        <Route path='admin-accounts' element={<AdminAccounts />}/>
        <Route path='create-admin' element={<AdminSignupPage />}/>
        <Route path='resident-accounts' element={<ResidentAccounts />}/>
        <Route path='unverified-residents' element={<UnverifiedResidents />}/>
        <Route path='registration-key' element={<RegistrationKey />}/>
        <Route path='admin-logs' element={<AdminLogs />}/>
        <Route path='*' element={<NotFound/>} />
      </Routes>
      </Layout>
      </ProtectedRoute>
    </Box>
  )
}

export default AdminApp
ProtectedRoute.propTypes = {
  children: PropTypes.any,
};
AdminApp.propTypes = {
  children: PropTypes.any,
};

import {Box} from '@chakra-ui/react'
import {Routes, Route, Navigate} from 'react-router-dom'
import {useEffect} from 'react'
import {useAuthStore} from '../store/auth'

import LoginPage from '../authPages/LoginPage'
import AdminLoginPage from '../authPages/AdminLoginPage'
import ResidentSignupPage from '../authPages/ResidentSignupPage'
import VerifySignup from '../authPages/VerifySignup'
import ForgotPassword from '../authPages/ForgotPassword'
import ForgotPasswordAdmin from '../authPages/ForgotPasswordAdmin'
import ResetPassword from '../authPages/ResetPassword'
import LoginPageOtp from '../authPages/LoginOtpPage'
import PleaseWaitForVerification from '../authPages/PleaseWaitForVerification'
import NotFound from '../components/NotFound'
import PropTypes from 'prop-types';

const RedirectAuthenticatedUser = ({ children }) => {
  const { isAuthenticated, user } = useAuthStore();

  if (isAuthenticated) {
    if (!user?.isVerified) {
      return <Navigate to='/auth/verify-signup-otp' replace />;
    } else if (user.role === 'admin') {
      return <Navigate to='/admin/reservations' replace />;
    } else if (user.role === 'resident') {
      return <Navigate to='/resident' replace />;
    } else {
      return <Navigate to='/' replace />;
    }
  }

  // User is not authenticated, so allow access to the auth pages
  return children;
};

function AuthApp() {
  const {checkAuth, isAuthenticated, user} = useAuthStore()

  useEffect(() => {
    checkAuth()
  }, [checkAuth])




  return (
    <Box>

      <Routes>

        <Route path='resident-login' element={
          <RedirectAuthenticatedUser>
            <LoginPage/>
          </RedirectAuthenticatedUser>
        } />

        <Route path='admin-login' element={
          <RedirectAuthenticatedUser>
            <AdminLoginPage/>
          </RedirectAuthenticatedUser>
        } />

        <Route path='resident-signup' element={
          <RedirectAuthenticatedUser>
            <ResidentSignupPage/>
          </RedirectAuthenticatedUser>
        } />

        <Route path='verify-signup-otp' element={<VerifySignup/>} />

        <Route path='forgot-password-resident' element={
          <RedirectAuthenticatedUser>
            <ForgotPassword/>
          </RedirectAuthenticatedUser>
        } />

        <Route path='forgot-password-admin' element={
          <RedirectAuthenticatedUser>
            <ForgotPasswordAdmin/>
          </RedirectAuthenticatedUser>
        } />

        <Route path='reset-password/:token' element={
          <RedirectAuthenticatedUser>
            <ResetPassword/>
          </RedirectAuthenticatedUser>
        } />

        <Route path='verify-login-otp' element={<LoginPageOtp/>} />

        <Route path='please-wait-for-verification' element={<PleaseWaitForVerification/>} />
        <Route path='*' element={<NotFound/>} />

      </Routes>

    </Box>
  )
}

export default AuthApp

RedirectAuthenticatedUser.propTypes = {
  children: PropTypes.any,
};
AuthApp.propTypes = {
  children: PropTypes.any,
};

import { useEffect, useState } from 'react';
import { Container, VStack,  Text, Alert, AlertIcon, Button, Input, InputGroup, InputLeftElement, Modal, ModalOverlay, ModalContent, ModalHeader, ModalBody, ModalFooter, Select, Textarea, useDisclosure, useToast, FormControl, FormLabel, Stack
} from '@chakra-ui/react';
import { SearchIcon } from '@chakra-ui/icons';
import { useListingStore } from '../store/listing';
import ListingCardAdmin from '../components/ListingCardAdmin';
import LoadingSpinner from '../components/LoadingSpinner';

const Listings = () => {

  const { listing, fetchListing, createListing, isLoading,  initializeSocketListeners } = useListingStore();
  const { isOpen, onOpen, onClose } = useDisclosure();
  const [newListing, setNewListing] = useState({
    name: '',
    description: '',
    inventory: '',
    address: '',
    image: null,
    type: '',
  });
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedType, setSelectedType] = useState('');
  const toast = useToast();

  useEffect(() => {
    fetchListing();
    initializeSocketListeners();
  }, []);

  const handleAddListing = async (e) => {
    e.preventDefault();

    try {
      await createListing(newListing);
      toast({
        title: 'Listing created.',
        description: 'The new listing has been successfully created.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
      // Reset form and close modal
      setNewListing({
        name: '',
        description: '',
        inventory: '',
        address: '',
        image: '',
        type: '',
      });
      onClose();
    } catch (error) {

      toast({
        title: 'Error',
        description: 'There was an creating the listing.',
        status: '',
        duration: 5000,
        isClosable: true});
    }
  };

  if (isLoading) return <LoadingSpinner />;

  if (error) {
    return (
      <Alert status="">
        <AlertIcon />
        Error fetching listings. Please try again later.
      </Alert>
    );
  }

    // To filter listings based on the search query
    const filteredListings = listing.filter((listing) => {
      const matchesSearch = listing.name.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesType = selectedType ? listing.type === selectedType : true;
      return matchesSearch && matchesType;
    });

  return (
    <>
    <Container maxW="container.xl" py={5}>
      <VStack spacing={4}>
        {/* Header Section */}
        <Stack direction={{ base: 'column', md: 'row' }} justifyContent="space-between" w="full" mb={8} flexWrap="wrap">
          {/* Title */}
          <Text fontSize="3xl" fontWeight="bold" color="blue.600">
            Equipments and Resources
          </Text>

          <Stack direction={{ base: 'column', md: 'row' }} w={{ base: 'full', md: 'auto' }}>
          <InputGroup width={{ base: 'full', md: '250px' }}>
              <InputLeftElement pointerEvents="none">
                <SearchIcon color="gray.400" />
              </InputLeftElement>
              <Input
                size="md"
                variant="outline"
                placeholder="Search by Listing Name"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
          </InputGroup>

          <Select
              placeholder="Show All" 
              variant="outline" 
              width={{ base: 'full', md: '150px' }}
              value={selectedType}
              onChange={(e) => setSelectedType(e.target.value)}
            >
              <option value="equipment">Equipment</option>
              <option value="facility">Facility</option>
          </Select>

          {/* Add New Listing Button */}
          <Button w={{ base: 'full', md: 'auto' }} colorScheme="blue" onClick={onOpen}>
              Add New Listing
          </Button>
          </Stack>
        </Stack>

        {/* Listings */}
        <VStack spacing={4} w="full">
          {filteredListings?.map((item) => (
            <ListingCardAdmin key={item._id} listing={item} />
          ))}

        {/* No Listings Message */}
        {(!filteredListings || filteredListings.length === 0) && (
          <Text fontSize={'2xl'} textAlign={'center'} fontWeight={'bold'} color={'gray.500'}>
            No Listings Available
          </Text>
        )}
        </VStack>
      </VStack>
    </Container>

  {/* Modal for creating new listings */}
  <Modal isOpen={isOpen} onClose={onClose} size={{ base: 'full', md: 'md' }} isCentered closeOnOverlayClick={false}>
    <ModalOverlay />
    <ModalContent borderRadius="md" overflow="hidden">
      {/* Header */}
      <ModalHeader bg="blue.600" color="white" fontSize="xl">
        Add New Listing
      </ModalHeader>

      <ModalBody bg="gray.50" py={6}>
        <form onSubmit={handleAddListing}>
          <VStack spacing={4} align="stretch">
            {/* Listing Name */}
            <FormControl isRequired>
              <FormLabel>Listing Name</FormLabel>
              <Input
                placeholder="Enter the name of the listing"
                name="name"
                value={newListing.name}
                onChange={(e) => setNewListing({ ...newListing, name: e.target.value })}
                focusBorderColor="blue.400"
                bg="white"
                borderColor="gray.300"
              />
            </FormControl>

            {/* Description */}
            <FormControl isRequired>
              <FormLabel>Description</FormLabel>
              <Textarea
                placeholder="Enter a detailed description of the listing"
                name="description"
                value={newListing.description}
                onChange={(e) => setNewListing({ ...newListing, description: e.target.value })}
                focusBorderColor="blue.400"
                bg="white"
                borderColor="gray.300"
              />
            </FormControl>

            {/* Type Select */}
            <FormControl isRequired>
              <FormLabel>Type</FormLabel>
              <Select
                placeholder="Select the type of listing"
                name="type"
                value={newListing.type}
                onChange={(e) => setNewListing({ ...newListing, type: e.target.value })}
                focusBorderColor="blue.400"
                bg="white"
                borderColor="gray.300"
              >
                <option value="equipment">Equipment</option>
                <option value="facility">Facility</option>
              </Select>
            </FormControl>

            {/* Inventory or Address Input */}
            {newListing.type === 'equipment' && (
              <FormControl isRequired>
                <FormLabel>Inventory</FormLabel>
                <Input
                  placeholder="Enter available inventory quantity"
                  name="inventory"
                  type="number"
                  value={newListing.inventory}
                  onChange={(e) => setNewListing({ ...newListing, inventory: e.target.value })}
                  focusBorderColor="blue.400"
                  bg="white"
                  borderColor="gray.300"
                />
              </FormControl>
            )}

            {newListing.type === 'facility' && (
              <FormControl isRequired>
                <FormLabel>Address</FormLabel>
                <Input
                  placeholder="Enter the facility address"
                  name="address"
                  value={newListing.address}
                  onChange={(e) => setNewListing({ ...newListing, address: e.target.value })}
                  focusBorderColor="blue.400"
                  bg="white"
                  borderColor="gray.300"
                />
              </FormControl>
            )}

            {/* Image Upload */}
            <FormControl isRequired>
              <FormLabel>Image URL</FormLabel>
              <Input
                type="url"
                placeholder="Enter image URL"
                value={newListing.image || ''}
                onChange={(e) => setNewListing({ ...newListing, image: e.target.value })}
                focusBorderColor="blue.400"
                bg="white"
                borderColor="gray.300"
              />
            </FormControl>
          </VStack>

          {/* Footer */}
          <ModalFooter justifyContent="space-between" px={0} mt={6} mb={-5}>
            <Button colorScheme="blue" type="submit" isLoading={isLoading}>
              Save
            </Button>
            <Button variant="ghost" onClick={onClose} borderWidth="1px">
              Cancel
            </Button>
          </ModalFooter>
        </form>
      </ModalBody>
    </ModalContent>
  </Modal>


    </>
  );
};

export default Listings;

import { Button, Flex, FormControl, FormLabel, Heading, Input, InputGroup, InputRightElement, Stack,
} from '@chakra-ui/react'
import { ViewIcon, ViewOffIcon } from '@chakra-ui/icons'
import { useState } from 'react'
import { useAuthStore } from '../store/auth';
import { useNavigate, useParams } from 'react-router-dom';
import { useToast } from '@chakra-ui/react';

function ResetPassword() {
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)

  const { resetPassword, isLoading } = useAuthStore();
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const { token } = useParams()
  const navigate = useNavigate()
  const toast = useToast()

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (password !== confirmPassword) {
      toast({
        title: 'User Error.',
        description: 'Passwords do not match.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      })
      return; // Return early if passwords do not match
    }

    try {
      await resetPassword(token, password)

      toast({
        title: 'Success.',
        description: 'Password reset successfully, you may close this tab now and login again.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
    } catch (error) {

      toast({
        title: 'Error.',
        description: error.message || 'Error resetting password.',
        status: 'error',
        duration: 5000,
        isClosable: true,
      })
    }
  }

  const toggleShowPassword = () => setShowPassword(!showPassword)
  const toggleShowConfirmPassword = () => setShowConfirmPassword(!showConfirmPassword)

  return (
    <Flex
      minH={'100vh'}
      align={'center'}
      justify={'center'}
      bg={'gray.50'}>
      <Stack
        as="form"
        onSubmit={handleSubmit}
        spacing={4}
        w={'full'}
        maxW={'md'}
        rounded={'xl'}
        boxShadow={'lg'}
        p={6}
        my={12}>
        <Heading lineHeight={1.1} fontSize={{ base: '2xl', md: '3xl' }}>
          Enter new password
        </Heading>
        <FormControl id="new-password" isRequired>
          <FormLabel>New Password</FormLabel>
          <InputGroup>
            <Input
              type={showPassword ? 'text' : 'password'}
              placeholder="Enter new password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
            <InputRightElement width="4.5rem">
              <Button h="1.75rem" size="sm" onClick={toggleShowPassword} variant="ghost">
                {showPassword ? <ViewOffIcon /> : <ViewIcon />}
              </Button>
            </InputRightElement>
          </InputGroup>
        </FormControl>
        <FormControl id="confirm-password" isRequired>
          <FormLabel>Confirm Password</FormLabel>
          <InputGroup>
            <Input
              type={showConfirmPassword ? 'text' : 'password'}
              placeholder="Re-enter new password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              required
            />
            <InputRightElement width="4.5rem">
              <Button h="1.75rem" size="sm" onClick={toggleShowConfirmPassword} variant="ghost">
                {showConfirmPassword ? <ViewOffIcon /> : <ViewIcon />}
              </Button>
            </InputRightElement>
          </InputGroup>
        </FormControl>
        <Stack spacing={6}>
          <Button
            type='submit'
            bg={'blue.400'}
            color={'white'}
            _hover={{
              bg: 'blue.500',
            }}>
            {isLoading ? 'Resetting Password...' : 'Set New Password'}
          </Button>
        </Stack>
      </Stack>
    </Flex>
  )
}

export default ResetPassword;

import { useState } from 'react'
import { Center, Heading, Text, useToast } from '@chakra-ui/react'
import { Button, FormControl, Flex, Stack, Box, useColorModeValue, HStack,
} from '@chakra-ui/react'
import { PinInput, PinInputField } from '@chakra-ui/react'
import { useNavigate } from 'react-router-dom'
import { useAuthStore } from '../store/auth'

export default function VerifySignup() {
  const [code, setCode] = useState('')
  const toast = useToast()
  const navigate = useNavigate()

  const { error, isLoading, verifySignup } = useAuthStore()

  const handleVerify = async (e) => {
    e.preventDefault()
    try {
      const response = await verifySignup(code)
      const role = response.user.role

      toast({
        title: 'Email Verified.',
        description: 'Your email has been verified successfully.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      })

      if (role === 'admin') {
        navigate('/admin/reservations')
      } else if (role === 'resident') {
        navigate('/resident')
      }
    } catch (err) {
      toast({
        title: 'Error',
        description: err.response?.data?.message || 'Error verifying email',
        status: 'error',
        duration: 5000,
        isClosable: true,
      })
    }

  }

  return (
    <Flex
      minH={'100vh'}
      align={'center'}
      justify={'center'}
      px={4}
      bg={useColorModeValue('gray.50', 'gray.900')}
    >
      <Box
        w={{ base: 'full', md: 'lg' }}
        bg={useColorModeValue('white', 'gray.800')}
        rounded={'lg'}
        boxShadow={'lg'}
        p={8}
        mx={{ base: 4, md: 0 }}
      >
        <Stack spacing={6}>
          <Center>
            <Heading fontSize={{ base: '2xl', md: '3xl' }}>
              Verify Your Phone or Email
            </Heading>
          </Center>
          <Text
            textAlign={'center'}
            fontSize={{ base: 'sm', md: 'md' }}
            color={useColorModeValue('gray.600', 'gray.400')}
          >
            We have sent a 6-digit code to your phone or email. Please enter it
            below to verify your account.
          </Text>
          <FormControl>
            <Center>
              <HStack>
                <PinInput onChange={(value) => setCode(value)} size="md">
                  <PinInputField />
                  <PinInputField />
                  <PinInputField />
                  <PinInputField />
                  <PinInputField />
                  <PinInputField />
                </PinInput>
              </HStack>
            </Center>
          </FormControl>
          <Stack spacing={6}>
            <Button
              w={'full'}
              bg={'blue.400'}
              color={'white'}
              isLoading={isLoading}
              _hover={{
                bg: 'blue.500',
              }}
              onClick={handleVerify}
            >
              Verify
            </Button>
          </Stack>
        </Stack>
      </Box>
    </Flex>
  )
}

import React, { useEffect, useState, forwardRef } from 'react';
import { Box, Text, HStack, VStack, Icon, Button, Modal, ModalOverlay, ModalContent, ModalHeader, ModalBody, ModalFooter, useDisclosure, Flex, Input, Textarea, useToast, FormControl, FormLabel, Select, Stack
} from '@chakra-ui/react';
import { FaClipboardList, FaUser, FaMapMarkerAlt, FaPhone, FaIdBadge } from 'react-icons/fa';
import { useReservationStore } from '../store/reservation.js'
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import styled from 'styled-components';
import PropTypes from 'prop-types';

const ReservationCardAdmin = React.memo(
  (({ isOpen, onOpen, onClose, reservation, bookings, listings, deleteReservation }) => {

  const { updateReservationAdmin } = useReservationStore();

  const {
    isOpen: isEditOpen,
    onOpen: onEditOpen,
    onClose: onEditClose,
  } = useDisclosure();

  const toast = useToast()

  const [localListings, setLocalListings] = useState(listings);

  const [appointmentDate, setAppointmentDate] = useState(null);
  const [selectedDate, setSelectedDate] = useState(null);
  const [excludeTimesForDate, setExcludeTimesForDate] = useState([]);
  const [initialRemarks, setInitialRemarks] = useState('');
  const [adminMessage, setAdminMessage] = useState('');
  const [dateError, setDateError] = useState(false);

  const [editedPurpose, setEditedPurpose] = useState(reservation?.purpose || '');
  const [editedStartDate, setEditedStartDate] = useState(reservation?.startDate || '');
  const [editedEndDate, setEditedEndDate] = useState(reservation?.endDate || '');
  const [editedStatus, setEditedStatus] = useState(reservation?.status || '');
  const [editedResources, setEditedResources] = useState(
    reservation?.resources?.map((item) => ({
      ...item,
      originalQuantity: item.quantity,
    })) || []
  );

  // Function to get the color based on the status
  const getStatusColor = (status) => {
    switch (status) {
      case 'Pending':
        return 'yellow.100'; // Light yellow
      case 'Approved':
        return 'green.100'; // Light green
      case 'Declined':
        return 'red.100'; // Light red
      case 'In-Use':
        return 'blue.100'; // Light blue
      case 'Returned':
        return 'orange.100'; // Light orange
      default:
        return 'gray.100'; // Default color
    }
  };

  const createTime = (date, hours, minutes) => {
    const newDate = new Date(date);
    newDate.setHours(hours, minutes, 0, 0);
    return newDate;
  };

  // Helper function to calculate total slots
  const calculateTotalSlots = (start, end, interval) => {
    const startInMinutes = start.hours * 60 + start.minutes;
    const endInMinutes = end.hours * 60 + end.minutes;
    const totalMinutes = endInMinutes - startInMinutes;
    return totalMinutes / interval;
  };

  const BUSINESS_HOURS_START = { hours: 8, minutes: 30 }; // 8:30 AM
  const BUSINESS_HOURS_END = { hours: 16, minutes: 30 };  // 4:30 PM

  const lunchBreakTimes = selectedDate
  ? [
      createTime(selectedDate, 12, 0),  // 12:00 PM
      createTime(selectedDate, 12, 30),  // 1:00 PM
    ]
  : [];

  const minTime = selectedDate
  ? createTime(selectedDate, BUSINESS_HOURS_START.hours, BUSINESS_HOURS_START.minutes)
  : createTime(new Date(), BUSINESS_HOURS_START.hours, BUSINESS_HOURS_START.minutes);

const maxTime = selectedDate
  ? createTime(selectedDate, BUSINESS_HOURS_END.hours, BUSINESS_HOURS_END.minutes)
  : createTime(new Date(), BUSINESS_HOURS_END.hours, BUSINESS_HOURS_END.minutes);

  // Custom input for the time picker
  const CustomInput = forwardRef(({ value, onClick }, ref) => (
    <Input
    onClick={onClick}
    value={value}
    ref={ref}
    placeholder="Select appointment date and time"
    readOnly
    width="full"
    cursor="pointer"
    _hover={{ borderColor: 'blue.500' }}
  />
  ));

  // Calendar Container for DatePicker
  const CalendarContainer = ({ children }) => {
    return (
      <Box zIndex={1500} position="relative">
        {children}
      </Box>
    );
  };

  // Styled DatePickerWrapper
  const DatePickerWrapper = styled.div`
  .react-datepicker-wrapper,
  .react-datepicker__input-container {
    display: block;
    width: 100%;
  }

  .react-datepicker__time-container {
    width: 120px;
  }

  .react-datepicker__time-box {
    width: 120px !important;
  }
`;

  // Update excludeTimesForDate when selectedDate changes
  useEffect(() => {


  
    if (selectedDate) {
      const dateKey = selectedDate.toISOString().split('T')[0];

  
      const bookedTimes = bookings[dateKey] || [];

  
      // Calculate total available slots (e.g., 30-minute intervals)
      const interval = 30; // minutes
      const totalSlots = calculateTotalSlots(BUSINESS_HOURS_START, BUSINESS_HOURS_END, interval);

  
      if (bookedTimes.length < totalSlots) {
        const times = bookedTimes.map((bookedTime) => {
          const bookedDate = new Date(bookedTime);
          const time = createTime(selectedDate, bookedDate.getHours(), bookedDate.getMinutes());

          return time;
        });
  

        setExcludeTimesForDate(times);
      } else {

        setExcludeTimesForDate([]);
      }
    } else {
      setExcludeTimesForDate([]);
    }
  }, [selectedDate, bookings]);


  // Combine booked times with lunch break times
  const excludeTimes = excludeTimesForDate.concat(lunchBreakTimes);


  // Function to handle APPROVING a reservation
  const handleApprove = async (event) => {
    event.preventDefault();
    try {

      if (!appointmentDate) {
        setDateError(true);
        toast({
          title: 'Appointment Date Required',
          description: 'Please set an appointment date and time before approving.',
          status: 'warning',
          duration: 5000,
          isClosable: true,
        });
        return;
      }

    const appointmentDateObj = new Date(appointmentDate);

    // Verify that the appointmentDateObj is a valid date
    if (isNaN(appointmentDateObj.getTime())) {
      toast({
        title: 'Invalid Appointment Date',
        description: 'The selected appointment date and time is invalid.',
        status: '',
        duration: 5000,
        isClosable: true});
      return;
    }


      // Check if sufficient inventory is available for each resource
      for (const resource of reservation.resources) {
        // Find the latest inventory
        const listingResource = localListings.find(
          (item) => item._id === resource.resourceId._id
        );
  
        if (!listingResource) {
          toast({
            title: 'Resource Not Found',
            description: `Resource ${resource.resourceId.name} not found.`,
            status: 'error',
            duration: 5000,
            isClosable: true,
          });
          return;
        }
  
        if (listingResource.inventory < resource.quantity) {
          toast({
            title: 'Insufficient Inventory',
            description: `Not enough ${resource.resourceId.name} resource/s to cover the reservation.`,
            status: 'error',
            duration: 5000,
            isClosable: true,
          });
          return;
        }
      }
  
      const updates = {
        status: 'Approved',
        appointmentDate: appointmentDateObj,
        adminMessage: adminMessage,
        resources: reservation.resources.map(item => ({
          resourceId: item.resourceId._id,
          quantity: item.quantity
        }))
      };
  
      await updateReservationAdmin(reservation._id, updates);
  
      toast({
        title: 'Reservation approved.',
        description: 'The resident has been notified.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
      onClose();

    } catch (err) {

      toast({
        title: 'Error',
        description: response?.data?.message || 'Error approving reservation request.',
        status: '',
        duration: 5000,
        isClosable: true});
    }
  };

  // Function to handle DECLINING a reservation
  const handleDecline = async () => {
    event.preventDefault();
    try {

      if (!adminMessage) {
        toast({
          title: 'Admin Message Required',
          description: 'Please provide a decline reason why before declining.',
          status: 'warning',
          duration: 5000,
          isClosable: true,
        });
        return;
      }

      await updateReservationAdmin(reservation._id, 
        { status: 'Declined',
         adminMessage: adminMessage
        });
      toast({
        title: 'Reservation request declined.',
        description: 'Reservation request declined successfully, notifying resident now.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      })
      onClose();

    } catch (err) {

      toast({
        title: 'Error',
        description: response?.data?.message || 'Error declining reservation request.',
        status: '',
        duration: 5000,
        isClosable: true})
    }
  };

  // Function to handle makring a reservation as IN-USE
  const handleInUse = async () => {
    event.preventDefault();
    try {

      await updateReservationAdmin(reservation._id, { 
        status: 'In-Use',
        initialRemarks: initialRemarks
       });

      toast({
        title: 'Reservation status updated.',
        description: 'Reservation status updated to In-Use.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      })
      onClose();

    } catch (err) {

      toast({
        title: 'Error',
        description: response?.data?.message || 'Error updating reservation status.',
        status: '',
        duration: 5000,
        isClosable: true})
    }
  };

  // Function to handle EDITING A RESERVATION in approved status
  const handleEditReservation = async () => {
    onEditOpen(); // Open the edit modal
  };

      // Handle quantity change
      const handleQuantityChange = (index, quantity) => {
        if (/^\d*$/.test(quantity)) {
          setEditedResources((prevResources) => {
            const newResources = [...prevResources];
            newResources[index].quantity = quantity;
            return newResources;
          });
        }
      };

      // Handle removing a resource
      const handleRemoveResource = (resourceId) => {
        setEditedResources((prevResources) =>
          prevResources.filter((item) => item.resourceId._id !== resourceId)
        );
      };

      // Handle adding a new resource
      const handleAddResource = (event) => {
        const resourceId = event.target.value;
        const resource = localListings.find((item) => item._id === resourceId);
      
        if (resource && !editedResources.some((item) => item.resourceId._id === resourceId)) {
          const defaultQuantity = resource.type === 'facility' ? 1 : 1; // Ensure quantity is set to 1 for facilities
          setEditedResources((prevResources) => [
            ...prevResources,
            { resourceId: resource, quantity: defaultQuantity, originalQuantity: resource.type === 'facility' ? 1 : 0 },
          ]);
        }
      };

  // Function to handle UPDATING A RESERVATION
  const handleUpdateReservation = async (event) => {
    event.preventDefault();
  
    // Validate all fields before proceeding
    let hasErrors = false;
  
    // Validate purpose
    if (!editedPurpose.trim()) {
      toast({
        title: 'Invalid Input',
        description: 'Reservation purpose cannot be empty.',
        status: '',
        duration: 5000,
        isClosable: true});
      hasErrors = true;
    }
  
    // Validate dates
    if (!editedStartDate || !editedEndDate) {
      toast({
        title: 'Invalid Input',
        description: 'Start and End dates must be provided.',
        status: '',
        duration: 5000,
        isClosable: true});
      hasErrors = true;
    } else if (new Date(editedStartDate) > new Date(editedEndDate)) {
      toast({
        title: 'Invalid Dates',
        description: 'Start date cannot be later than the end date.',
        status: '',
        duration: 5000,
        isClosable: true});
      hasErrors = true;
    } 
  
    // Validate resources
    const invalidResources = editedResources.filter(
      (item) => item.quantity <= 0 || !item.quantity
    );
  
    if (invalidResources.length > 0) {
      toast({
        title: 'Invalid Resource Quantity',
        description: 'Each resource/s must have a valid quantity greater than 0.',
        status: '',
        duration: 5000,
        isClosable: true});
      hasErrors = true;
    }
  
    // Stop the operation if there are validation errors
    if (hasErrors) return;
  
    try {
      // Prepare updated data for submission
      const updatedData = {
        purpose: editedPurpose,
        startDate: editedStartDate,
        endDate: editedEndDate,
        resources: editedResources.map((item) => ({
          resourceId: item.resourceId._id || item.resourceId,
          quantity: item.quantity,
        })),
        status: editedStatus,
      };

      if (editedStatus === 'Pending') {
        updatedData.appointmentDate = null;
      };
  
      // Perform the update operation
      await updateReservationAdmin(reservation._id, updatedData);
  
      // Show success message
      toast({
        title: 'Reservation Updated',
        description: 'The reservation details have been updated successfully.',
        status: 'success',
        duration: 5000,
        isClosable: true,
      });
  
      onEditClose(); // Close the modal
  
    } catch (err) {

  
      // Show message
      toast({
        title: 'Error',
        description: 'An error occurred while updating the reservation.',
        status: 'error',
        duration: 5000,
        isClosable: true});
    }
  };

      // Handle canceling the edit button
      const handleEditCancel = () => {
        onEditClose(); // Close the edit modal
      };

  // Function to handle setting back to PENDING status FROM DECLINED status
  const handlePending = async () => {
    event.preventDefault();
    try {
      await updateReservationAdmin(reservation._id, { status: 'Pending' });
      toast({
        title: 'Reservation status updated.',
        description: 'Reservation status updated back to Pending.',
        status: 'success',
