                </Text>
                <Text
                  color={
                    reservation.status === 'Pending'
                      ? 'yellow.600'
                      : reservation.status === 'Approved'
                      ? 'green.600'
                      : 'red.600'
                  }
                  fontWeight="bold"
                  fontSize="md"
                  bg={
                    reservation.status === 'Pending'
                      ? 'yellow.100'
                      : reservation.status === 'Approved'
                      ? 'green.100'
                      : 'red.100'
                  }
                  p={3}
