              <VStack spacing={4} w="full" align="stretch">
                {/* Purpose */}
                <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth='1px'>
                  <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                    Purpose
                  </Text>
                  <Text
                    color="gray.700"
                    fontSize="md"
                    bg="gray.100"
                    p={3}
                    borderRadius="md"
                    fontWeight="bold"
                  >
                    {reservation.purpose}
                  </Text>
                </Box>

                {/* Appointment Date and Time */}
                <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth='1px'>
                  <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                    Appointment Details
                  </Text>
                  <Text
                    color="gray.700"
                    fontSize="md"
                    bg="gray.100"
                    p={3}
                    borderRadius="md"
                    fontWeight="bold"
                  >
                    {new Date(reservation.appointmentDate).toLocaleDateString('en-US', {
                      day: 'numeric',
                      month: 'long',
                      year: 'numeric',
                    })} at{' '}
                    {new Date(reservation.appointmentDate).toLocaleTimeString('en-US', {
                        timeZone: 'Asia/Manila', // UTC+8
                        hour: 'numeric',
                        minute: 'numeric',
                        hour12: true,
                      })}
                  </Text>
                </Box>
              </VStack>


              {/* Dates */}
              <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth='1px'>
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Date/s Needed
                </Text>
                <Stack direction={{ base: 'column', md: 'row' }} w='full' spacing={4}>
                  <VStack align="start" w={{ base: 'full', md: '50%' }}>
                    <Text  color="gray.600" fontSize="md">
                      Start Date:
                    </Text>
                    <Text color="blue.600" fontSize="md" fontWeight="bold">
                      {new Date(reservation.startDate).toLocaleDateString()}
                    </Text>
                  </VStack>
                  <VStack align="start" w={{ base: 'full', md: '50%' }}>
                    <Text  color="gray.600" fontSize="md">
                      End Date:
                    </Text>
                    <Text color="blue.600" fontSize="md" fontWeight="bold">
                      {new Date(reservation.endDate).toLocaleDateString()}
                    </Text>
                  </VStack>
                </Stack>
              </Box>

              {/* Admin Message */}
              <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth='1px'>
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Admin Message
                </Text>
                <Text color="gray.700" fontSize="md" bg="gray.100" p={3} borderRadius="md">
                  {reservation.adminMessage}
                </Text>
              </Box> 

              {/* Initial Remarks */}
              <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth='1px'>
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Initial Remarks
                </Text>
                <Textarea
                  placeholder='Enter initial remarks here...'
                  value={initialRemarks} // Controlled state for the remark
                  onChange={(e) => setInitialRemarks(e.target.value)} // Handle change
                  bg="gray.100"
                  color="gray.700"
                  borderRadius="md"
                  fontSize="md"
                  p={3}
                />
              </Box>
 

              {/* Status */}
              <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth='1px'>
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Status
                </Text>
                <Text
                  color={
                    reservation.status === 'Pending'
                      ? 'yellow.600'
                      : reservation.status === 'Approved'
                      ? 'green.600'
                      : 'red.600'
                  }
                  fontWeight="bold"
                  fontSize="md"
                  bg={
                    reservation.status === 'Pending'
                      ? 'yellow.100'
                      : reservation.status === 'Approved'
                      ? 'green.100'
                      : 'red.100'
                  }
                  p={3}
                  borderRadius="md"
                >
                  {reservation.status}
                </Text>
              </Box>
            </VStack>
          </ModalBody>

          <ModalFooter justifyContent="space-between" p={6}>
            {/* Action Buttons */}
            <HStack spacing={3}>
              <Button
                colorScheme="green"
                _hover={{ bg: 'green.600' }} 
                bg="green.500"
                onClick={handleInUse}
              >
                Provide Resource/s
              </Button>
              <Button
                colorScheme="red"
                _hover={{ bg: 'yellow.600' }} 
                bg="yellow.500"
                onClick={handleEditReservation}
              >
                Edit Reservation
              </Button>
            </HStack>
            <Button variant="outline" onClick={onClose}>
              Close
            </Button>
          </ModalFooter>
        </ModalContent>
        
      </Modal>
      )}
      
      {/* Edit Reservation Modal */}
      <Modal isOpen={isEditOpen} onClose={handleEditCancel} size={{ base: 'full', md: 'xl' }} isCentered closeOnOverlayClick={false} scrollBehavior="inside">
          <ModalOverlay/>
          <ModalContent h="90vh" maxH="100vh" borderRadius="lg">
            <ModalHeader
              fontWeight="bold"
              fontSize="xl"
              color="white"
              bg="blue.600"
              px={6}
              py={4}
              borderTopRadius="lg"
            >
              Edit Reservation
            </ModalHeader>

            <ModalBody 
              overflowY="auto"
              px={6} 
              py={4}
            >
              <VStack spacing={5} align="stretch">

                {/* Current Resource Inventory */}
                <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
                  <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                    Current Resource/s Inventory
                  </Text>
                  <VStack align="start" spacing={3} w="full">
                    {reservation.resources.map((item) => (
                      <HStack key={item.resourceId._id} justifyContent="space-between" w="full">
                        <Text color="gray.700" fontSize="md">{item.resourceId.name}</Text>
                        {item.resourceId.type !== 'facility' ? (
                          <Text color="red.500" fontWeight="bold">Available: {item.resourceId.inventory}</Text>
                        ) : (
                          <Text color={item.isTaken ? 'red.500' : 'green.500'} fontWeight="bold">
                            {item.isTaken ? 'Not Available' : 'Available'}
                          </Text>
                        )}
                      </HStack>
                    ))}
                  </VStack>
                </Box>

                {/* Editable Resources List */}
                <Box p={4} bg="gray.50" borderRadius="md" borderWidth="1px">
                  <FormControl>
                    <FormLabel fontWeight="bold" color="gray.600" fontSize="lg">
                      Resource/s
                    </FormLabel>
                    <VStack align="stretch" spacing={4}>
                      {editedResources.map((item, index) => (
                        <HStack key={item.resourceId._id} spacing={4}>
                          <Text flex="1" fontWeight="medium" color="gray.700">
                            {item.resourceId.name}
                            {item.resourceId.type === 'facility' && item.resourceId.address && (
                              <> - {item.resourceId.address}</>
                            )}
                          </Text>
                          {item.resourceId.type !== 'facility' && (
                            <Input
                              type="number"
                              min={1}
                              max={item.resourceId.inventory + item.quantity} // Account for original quantity
                              value={item.quantity}
                              onChange={(e) => handleQuantityChange(index, e.target.value)}
                              width="100px"
                            />
                          )}
                          <Button
                            size="sm"
                            colorScheme="red"
                            onClick={() => handleRemoveResource(item.resourceId._id)}
                          >
                            Remove
                          </Button>
                        </HStack>
                      ))}
                    </VStack>
                  </FormControl>
                </Box>

                {/* Add New Resource */}
                <Box p={4} bg="gray.50" borderRadius="md" borderWidth="1px">
                  <FormControl>
                    <FormLabel fontWeight="bold" color="gray.600" fontSize="lg">
                      Add Resource
                    </FormLabel>
                    <Select placeholder="Select a resource" onChange={handleAddResource}>
                      {localListings.map((resource) => (
                        <option key={resource._id} value={resource._id}>
                          {resource.name}
                          {resource.type === 'facility' 
                      ? ` - ${resource.address}` 
                      : resource.name}
                        </option>
                      ))}
                    </Select>
                  </FormControl>
                </Box>

                {/* Purpose */}
                <Box p={4} bg="gray.50" borderRadius="md" borderWidth="1px">
                  <FormControl>
                    <FormLabel fontWeight="bold" color="gray.600" fontSize="lg">
                      Purpose
                    </FormLabel>
                    <Textarea
                      value={editedPurpose}
                      onChange={(e) => setEditedPurpose(e.target.value)}
                      bg="white"
                      borderRadius="md"
                    />
                  </FormControl>
                </Box>

                {/* Start and End Date */}
                <Box p={4} bg="gray.50" borderRadius="md" borderWidth="1px">
                  <FormControl>
                    <FormLabel fontWeight="bold" color="gray.600" fontSize="lg">
                      Date/s Needed
                    </FormLabel>
                    <Stack direction={{ base: 'column', md: 'row' }} spacing={6}>
                      <Box flex="1">
                        <FormControl>
                          <FormLabel fontWeight="medium" color="gray.600">
                            Start Date
                          </FormLabel>
                          <Input
                            type="date"
                            value={editedStartDate.substring(0, 10)}
                            onChange={(e) => setEditedStartDate(e.target.value)}
                            bg="white"
                            borderRadius="md"
                          />
                        </FormControl>
                      </Box>
                      <Box flex="1">
                        <FormControl>
                          <FormLabel fontWeight="medium" color="gray.600">
                            End Date
                          </FormLabel>
                          <Input
                            type="date"
                            value={editedEndDate.substring(0, 10)}
                            onChange={(e) => setEditedEndDate(e.target.value)}
                            bg="white"
                            borderRadius="md"
                          />
                        </FormControl>
                      </Box>
                    </Stack>
                  </FormControl>
                </Box>

                {/* Reservation Status */}
                <Box p={4} bg="gray.50" borderRadius="md" borderWidth="1px">
                <FormControl>
                  <FormLabel fontWeight="bold" color="gray.600" fontSize="lg">
                    Reservation Status
                  </FormLabel>
                  <Select
                    placeholder="Change Status"
                    value={editedStatus}
                    onChange={(e) => setEditedStatus(e.target.value)}
                    bg="white"
                    borderRadius="md"
                  >
                    <option value="Pending">Pending</option>
                    <option value="Declined">Declined</option>
                  </Select>
                </FormControl>
              </Box>

              </VStack>
            </ModalBody>

            <ModalFooter>
              <Button 
              colorScheme="blue" 
              mr={3} 
              onClick={handleUpdateReservation}
              type="button"
              >
                Save Changes
              </Button>
              <Button variant="outline" onClick={handleEditCancel}>
                Cancel
              </Button>
            </ModalFooter>
          </ModalContent>
      </Modal>

      {/* Modal popup for declined reservation requests */}    
      {reservation.status === 'Declined' && (            
      <Modal isOpen={isOpen} onClose={onClose} size={{ base: 'full', md: '3xl' }} isCentered scrollBehavior="inside" closeOnOverlayClick={false}>
        <ModalOverlay/>
        <ModalContent h="95vh" maxH="100vh" borderRadius="lg">
          <ModalHeader
            fontWeight="bold"
            fontSize="xl"
            color="white"
            bg="blue.600"
            px={6}
            py={4}
            borderTopRadius={'lg'}
          >
            Reservation Request Details
          </ModalHeader>
          <ModalBody p={6}>
            <VStack align="start" spacing={4} w="full">
              {/* Resident and Resources */}
              <Stack direction={{ base: 'column', md: 'row' }} align="start" spacing={6} w="full">
                {/* Resident Details */}
                <Box p={4} bg="gray.50" w={{ base: 'full', md: '50%' }} borderRadius="md" borderWidth='1px'>
                  <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                    Resident Info
                  </Text>
                  <VStack align="start" spacing={3} w="full">
                    <HStack justifyContent="space-between" w="full">
                      <Text color="gray.700" fontSize="md">Name:</Text>
                      <Text color="blue.600" fontWeight="bold">
                        {reservation.resident.firstname} {reservation.resident.middlename} {reservation.resident.lastname} {reservation.resident.suffix}
                      </Text>
                    </HStack>
                    <HStack justifyContent="space-between" w="full">
                      <Text color="gray.700" fontSize="md">Phone:</Text>
                      <Text color="blue.600" fontWeight="bold">
                        {reservation.resident.phone}
                      </Text>
                    </HStack>
                    <HStack justifyContent="space-between" w="full">
                      <Text color="gray.700" fontSize="md">Address:</Text>
                      <Text color="blue.600" fontWeight="bold">
                        B{reservation.resident.blknum} L{reservation.resident.lotnum}, Sitio {reservation.resident.sitio}
                      </Text>
                    </HStack>
                  </VStack>
                </Box>

                {/* Resources */}
                <Box p={4} bg="gray.50" w={{ base: 'full', md: '50%' }} borderRadius="md" borderWidth='1px'>
                  <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                    Resource/s
                  </Text>
                  <VStack align="start" spacing={3} w="full">
                    {reservation.resources.map((item) => (
                      <HStack key={item.resourceId._id} justifyContent="space-between" w="full">
                        <Text color="gray.700" fontSize="md">
                          {item.resourceId.name}
                          {item.resourceId.type === 'facility' && item.resourceId.address && (
                            <> - {item.resourceId.address}</>
                          )}
                        </Text>
                        {item.resourceId.type !== 'facility' && (
                          <Text color="blue.600" fontWeight="bold" fontSize="sm">
                            x {item.quantity}
                          </Text>
                        )}
                      </HStack>
                    ))}
                  </VStack>
                </Box>
              </Stack>

              {/* Current Resource Inventory */}
              <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Current Resource/s Inventory
                </Text>
                <VStack align="start" spacing={3} w="full">
                  {reservation.resources.map((item) => (
                    <HStack key={item.resourceId._id} justifyContent="space-between" w="full">
                      <Text color="gray.700" fontSize="md">{item.resourceId.name}</Text>
                      {item.resourceId.type !== 'facility' ? (
                        <Text color="red.500" fontWeight="bold">Available: {item.resourceId.inventory}</Text>
                      ) : (
                        <Text color={item.isTaken ? 'red.500' : 'green.500'} fontWeight="bold">
                          {item.isTaken ? 'Not Available' : 'Available'}
                        </Text>
                      )}
                    </HStack>
                  ))}
                </VStack>
              </Box>

              {/* Purpose and Appointment Date */}
              <HStack spacing={4} w="full" align="stretch">
                {/* Purpose */}
                <Box p={4} bg="gray.50" w="100%" borderRadius="md" borderWidth='1px'>
                  <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                    Purpose
                  </Text>
                  <Text
                    color="gray.700"
                    fontSize="md"
                    bg="gray.100"
                    p={3}
                    borderRadius="md"
                    fontWeight="bold"
                  >
                    {reservation.purpose}
                  </Text>
                </Box>
              </HStack>

              {/* Dates */}
              <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth='1px'>
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Date/s Needed
                </Text>
                <Stack direction={{ base: 'column', md: 'row' }} w='full' spacing={4}>
                  <VStack align="start" w={{ base: 'full', md: '50%' }}>
                    <Text  color="gray.600" fontSize="md">
                      Start Date:
                    </Text>
                    <Text color="blue.600" fontSize="md" fontWeight="bold">
                      {new Date(reservation.startDate).toLocaleDateString()}
                    </Text>
                  </VStack>
                  <VStack align="start" w={{ base: 'full', md: '50%' }}>
                    <Text  color="gray.600" fontSize="md">
                      End Date:
                    </Text>
                    <Text color="blue.600" fontSize="md" fontWeight="bold">
                      {new Date(reservation.endDate).toLocaleDateString()}
                    </Text>
                  </VStack>
                </Stack>
              </Box>

              {/* Admin Message */}
              <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth='1px'>
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Admin Message
                </Text>
                <Text color="gray.700" fontSize="md" bg="gray.100" p={3} borderRadius="md">
                  {reservation.adminMessage}
                </Text>
              </Box> 

              {/* Status */}
              <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth='1px'>
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Status
                </Text>
                <Text
                  color={
                    reservation.status === 'Pending'
                      ? 'yellow.600'
                      : reservation.status === 'Approved'
                      ? 'green.600'
                      : 'red.600'
                  }
                  fontWeight="bold"
                  fontSize="md"
                  bg={
                    reservation.status === 'Pending'
                      ? 'yellow.100'
                      : reservation.status === 'Approved'
                      ? 'green.100'
                      : 'red.100'
                  }
                  p={3}
                  borderRadius="md"
                >
                  {reservation.status}
                </Text>
              </Box>
            </VStack>
          </ModalBody>
          <ModalFooter justifyContent="space-between" p={6}>
            {/* Action Buttons */}
            <HStack spacing={3}>
              <Button
                colorScheme="green"
                _hover={{ bg: 'yellow.600' }} 
                bg="yellow.500"
                onClick={handlePending}
              >
                Set Back to Pending
              </Button>
              <Button colorScheme="red" onClick={handleDeleteReservation}>
                Delete Reservation
              </Button>
            </HStack>
            <Button variant="outline" onClick={onClose}>
              Close
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
      )} 

      {/* Modal popup for In-Use reservation requests */}
      {reservation.status === 'In-Use' && (
      <Modal isOpen={isOpen} onClose={onClose} size={{ base: 'full', md: '3xl' }} isCentered scrollBehavior="inside" closeOnOverlayClick={false}>
      <ModalOverlay />
      <ModalContent h="95vh" maxH="100vh" borderRadius="lg">
        <ModalHeader
          fontWeight="bold"
          fontSize="xl"
          color="white"
          bg="blue.600"
          px={6}
          py={4}
          borderTopRadius="lg"
        >
          In-Use Reservation Details
        </ModalHeader>
        <ModalBody p={6}>
          <VStack align="start" spacing={4} w="full">
            {/* Resident and Resources */}
            <Stack direction={{ base: 'column', md: 'row' }} align="start" spacing={6} w="full">
              {/* Resident Details */}
              <Box p={4} bg="gray.50" w={{ base: 'full', md: '50%' }} borderRadius="md" borderWidth="1px">
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Resident Info
                </Text>
                <VStack align="start" spacing={3} w="full">
                  <HStack justifyContent="space-between" w="full">
                    <Text color="gray.700" fontSize="md">Name:</Text>
                    <Text color="blue.600" fontWeight="bold">
                      {reservation.resident.firstname} {reservation.resident.middlename} {reservation.resident.lastname} {reservation.resident.suffix}
                    </Text>
                  </HStack>
                  <HStack justifyContent="space-between" w="full">
                    <Text color="gray.700" fontSize="md">Phone:</Text>
                    <Text color="blue.600" fontWeight="bold">
                      {reservation.resident.phone}
                    </Text>
                  </HStack>
                  <HStack justifyContent="space-between" w="full">
                    <Text color="gray.700" fontSize="md">Address:</Text>
                    <Text color="blue.600" fontWeight="bold">
                      B{reservation.resident.blknum} L{reservation.resident.lotnum}, Sitio {reservation.resident.sitio}
                    </Text>
                  </HStack>
                </VStack>
              </Box>
    
              {/* Resources */}
              <Box p={4} bg="gray.50" w={{ base: 'full', md: '50%' }} borderRadius="md" borderWidth="1px">
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Resource/s
                </Text>
                <VStack align="start" spacing={3} w="full">
                  {reservation.resources.map((item) => (
                    <HStack key={item.resourceId._id} justifyContent="space-between" w="full">
                      <Text color="gray.700" fontSize="md">{item.resourceId.name}</Text>
                      <Text color="blue.600" fontWeight="bold">x {item.quantity}</Text>
                    </HStack>
                  ))}
                </VStack>
              </Box>
            </Stack>
    
            {/* Current Resource Inventory */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
                <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                  Current Resource/s Inventory
                </Text>
                <VStack align="start" spacing={3} w="full">
                  {reservation.resources.map((item) => (
                    <HStack key={item.resourceId._id} justifyContent="space-between" w="full">
                      <Text color="gray.700" fontSize="md">{item.resourceId.name}</Text>
                      {item.resourceId.type !== 'facility' ? (
                        <Text color="red.500" fontWeight="bold">Available: {item.resourceId.inventory}</Text>
                      ) : (
                        <Text color={item.resourceId.inventory === 0 ? 'red.500' : 'green.500'} fontWeight="bold">
                          {item.resourceId.inventory === 0 ? 'Not Available' : 'Available'}
                        </Text>
                      )}
                    </HStack>
                  ))}
                </VStack>
              </Box>
    
            {/* Purpose */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Purpose
              </Text>
              <Text
                color="gray.700"
                fontSize="md"
                bg="gray.100"
                p={3}
                borderRadius="md"
                fontWeight="bold"
              >
                {reservation.purpose}
              </Text>
            </Box>
    
            {/* Dates */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Date/s Needed
              </Text>
              <Stack direction={{ base: 'column', md: 'row' }} w="full" spacing={4}>
                <VStack align="start" w={{ base: 'full', md: '50%' }}>
                  <Text color="gray.600" fontSize="md">
                    Start Date:
                  </Text>
                  <Text color="blue.600" fontSize="md" fontWeight="bold">
                    {new Date(reservation.startDate).toLocaleDateString()}
                  </Text>
                </VStack>
                <VStack align="start" w={{ base: 'full', md: '50%' }}>
                  <Text color="gray.600" fontSize="md">
                    End Date:
                  </Text>
                  <Text color="blue.600" fontSize="md" fontWeight="bold">
                    {new Date(reservation.endDate).toLocaleDateString()}
                  </Text>
                </VStack>
              </Stack>
            </Box>
    
            {/* Admin Message */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Initial Remarks
              </Text>
              <Text
                color="gray.700"
                fontSize="md"
                bg="gray.100"
                p={3}
                borderRadius="md"
                fontWeight="bold"
              >
                {reservation.initialRemarks}
              </Text>
            </Box>

            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Returned Remarks
              </Text>
              <Textarea
                placeholder='Enter returned remarks here...'
                color="gray.700"
                fontSize="md"
                bg="gray.100"
                p={3}
                borderRadius="md"
                value={reservation.returnedRemarks}
              />
            </Box>
    
            {/* Status */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Status
              </Text>
              <Text
                color={
                  reservation.status === 'In-Use'
                    ? 'orange.600'
                    : reservation.status === 'Completed'
                    ? 'green.600'
                    : 'red.600'
                }
                fontWeight="bold"
                fontSize="md"
                bg={
                  reservation.status === 'In-Use'
                    ? 'orange.100'
                    : reservation.status === 'Completed'
                    ? 'green.100'
                    : 'red.100'
                }
                p={3}
                borderRadius="md"
              >
                {reservation.status}
              </Text>
            </Box>
          </VStack>
        </ModalBody>
        <ModalFooter justifyContent="space-between" p={6}>
          <Button colorScheme='green' onClick={handleReturned}>
            Mark as Returned
          </Button>
          <Button variant="outline" onClick={onClose}>
            Close
          </Button>
        </ModalFooter>
      </ModalContent>
      </Modal>
      )}

      {/* Modal popup for Returned reservation requests */}
      {reservation.status === 'Returned' && (
      <Modal isOpen={isOpen} onClose={onClose} size={{ base: 'full', md: '3xl' }} isCentered scrollBehavior="inside" closeOnOverlayClick={false}>
      <ModalOverlay />
      <ModalContent h="95vh" maxH="100vh" borderRadius="lg">
        <ModalHeader
          fontWeight="bold"
          fontSize="xl"
          color="white"
          bg="blue.600"
          px={6}
          py={4}
          borderTopRadius="lg"
        >
          In-Use Reservation Details
        </ModalHeader>
        <ModalBody p={6}>
          <VStack align="start" spacing={4} w="full">
            {/* Resident and Resources */}
