            </Box>

            {/* Requested On */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Requested On
              </Text>
              <Text
                color="gray.700"
                fontSize="md"
                bg="gray.100"
                p={3}
                borderRadius="md"
                fontWeight="bold"
              >
                {new Date(reservation.createdAt).toLocaleString('en-US', {
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric',
                  hour: 'numeric',
                  minute: 'numeric',
                  hour12: true,
                })}
              </Text>
            </Box>
    
            {/* Purpose */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Purpose
              </Text>
              <Text
                color="gray.700"
                fontSize="md"
                bg="gray.100"
                p={3}
                borderRadius="md"
                fontWeight="bold"
              >
                {reservation.purpose}
              </Text>
            </Box>
    
            {/* Dates */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
