                </VStack>
                <VStack align="start" w={{ base: 'full', md: '50%' }}>
                  <Text color="gray.600" fontSize="md">
                    End Date:
                  </Text>
                  <Text color="blue.600" fontSize="md" fontWeight="bold">
                    {new Date(reservation.endDate).toLocaleDateString()}
                  </Text>
                </VStack>
              </Stack>
            </Box>
    
            {/* Admin Message */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Initial Remarks
              </Text>
              <Text
                color="gray.700"
                fontSize="md"
                bg="gray.100"
                p={3}
                borderRadius="md"
                fontWeight="bold"
              >
                {reservation.initialRemarks}
              </Text>
            </Box>

            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Returned Remarks
              </Text>
              <Text
                color="gray.700"
                fontSize="md"
                bg="gray.100"
                p={3}
                borderRadius="md"
                fontWeight="bold"
              >
                {reservation.returnedRemarks}
              </Text>
            </Box>

            
    
            {/* Status */}
            <Box p={4} bg="gray.50" w="full" borderRadius="md" borderWidth="1px">
              <Text fontWeight="bold" color="gray.600" fontSize="lg" mb={2}>
                Status
              </Text>
              <Text
                color={
                  reservation.status === 'In-Use'
                    ? 'orange.600'
                    : reservation.status === 'Completed'
                    ? 'green.600'
                    : 'red.600'
                }
                fontWeight="bold"
                fontSize="md"
                bg={
                  reservation.status === 'In-Use'
                    ? 'orange.100'
                    : reservation.status === 'Completed'
                    ? 'green.100'
                    : 'red.100'
                }
                p={3}
                borderRadius="md"
              >
                {reservation.status}
              </Text>
            </Box>
          </VStack>
        </ModalBody>
        <ModalFooter justifyContent="space-between" p={6}>
        <Button colorScheme="red" onClick={handleDeleteReservation}>
            Delete Reservation
        </Button>
          <Button variant="outline" onClick={onClose}>
            Close
          </Button>
        </ModalFooter>
      </ModalContent>
      </Modal>
      )}

    </>
    );
  }
));

